"""Serve the most recent evaluation report (generated by scripts/evaluate.py).

Read-only: it returns the cached report so the dashboard can show prediction
quality without clobbering the live simulator's state.
"""

from __future__ import annotations

import json
import os

from fastapi import APIRouter

router = APIRouter(prefix="/api/eval", tags=["eval"])

# routes -> api -> app -> backend (where scripts/evaluate.py writes the report)
_REPORT = os.path.join(os.path.dirname(__file__), "..", "..", "..", "eval_report.json")


@router.get("/report")
def report() -> dict:
    if not os.path.exists(_REPORT):
        return {"available": False}
    try:
        with open(_REPORT, encoding="utf-8") as f:
            data = json.load(f)
        data["available"] = True
        return data
    except Exception:  # noqa: BLE001
        return {"available": False}
